export const plotPosition=t=>new THREE.Vector3(t.lotX,.14,t.lotZ);
function coast(scale=1){const shape=new THREE.Shape();for(let i=0;i<=120;i++){const a=i/120*Math.PI*2,r=1+.06*Math.sin(a*5)+.035*Math.cos(a*3),x=21*scale*r*Math.cos(a),z=16.8*scale*r*Math.sin(a);if(i===0)shape.moveTo(x,-z);else shape.lineTo(x,-z);}shape.closePath();return shape;}
function shore(w,scale,y,color,depth=0){const geo=depth?new THREE.ExtrudeGeometry(coast(scale),{depth,bevelEnabled:false,curveSegments:64}):new THREE.ShapeGeometry(coast(scale),64),o=mesh(w,geo,color,[0,y,0]);o.rotation.x=-Math.PI/2;return o;}
export function buildIsland(scene){if(scene.tiles.forest){buildForestTown(scene);return;}scene.weatherGates=[];const TILES=scene.tiles;const w=scene.world;const sea=mesh(w,new THREE.PlaneGeometry(240,240),waterMaterial(),[0,-.69,0]);sea.rotation.x=-Math.PI/2;shore(w,1,-.5,'#ae9270',.48);shore(w,1.015,-.035,'#ebd69c');shore(w,.974,.025,'#86ad72');
 const seen=new Set();for(const a of TILES)for(const id of a.next){const b=TILES[id],key=[a.id,id].sort((x,y)=>x-y).join(':');if(seen.has(key))continue;seen.add(key);const length=Math.hypot(b.x-a.x,b.z-a.z),yaw=Math.atan2(b.x-a.x,b.z-a.z),x=(a.x+b.x)/2,z=(a.z+b.z)/2;for(const [width,height,color]of [[2.12,.07,'#e1cda5'],[1.68,.115,'#667b7b']]){const o=box(w,color,[x,height,z],[width,.035,length+.1]);o.rotation.y=yaw;}if(length>1.5){const dash=box(w,'#e8d6a0',[x,.142,z],[.035,.012,Math.min(.42,length*.3)]);dash.rotation.y=yaw;}}
 for(const t of TILES){cylinder(w,'#e1cda5',[t.x,.07,t.z],1.05,1.05,.04,24);cylinder(w,'#667b7b',[t.x,.115,t.z],.83,.83,.035,24);const g=new THREE.Group();g.userData.dynamic=true;g.position.set(t.x,0,t.z);g.rotation.y=t.yaw;w.add(g);const tile=box(g,'#718784',[0,.15,0],[1.6,.025,1.2]);tile.userData.tile=t.id;scene.tileMeshes.push(tile);const color=t.kind==='property'?GROUPS[t.group].color:({start:'#f2cd54',bank:'#5f9fc1',hospital:'#e1837b',stock:'#9c8bd1',shop:'#e8a25e',spirit:'#d7b658',event:'#d883a3',rest:'#82b678',tax:'#78b6ae'}[t.kind]);const curb=box(g,color,[0,.2,.52],[1.55,.07,.12]);curb.userData.tile=t.id;scene.tileMeshes.push(curb);const number=mesh(g,new THREE.PlaneGeometry(.6,.18),new THREE.MeshBasicMaterial({map:signTexture(String(t.id+1),{width:96,height:48,background:'#718784',color:'#fff3cf'}),depthWrite:false}),[0,.17,.16]);number.rotation.x=-Math.PI/2;
 if(t.kind!=='property'){const model=landmark(t);model.position.copy(plotPosition(t));model.rotation.y=t.facing;model.userData.dynamic=true;scene.tag(model,t.id);w.add(model);scene.tileMeshes.push(model);const names={bank:'银行',hospital:'疗养院',stock:'证券所',shop:'补给站',spirit:'神殿',event:'事件',rest:'小窝',tax:'清洁站',start:'起点'};const colors={bank:'#477eb5',hospital:'#cc615d',stock:'#7b65b0',shop:'#cf8342',spirit:'#af8535',event:'#ae6686',rest:'#5b8b55',tax:'#558e88',start:'#a18a3c'};const badge=landmarkBadge(model,t.id,names[t.kind],colors[t.kind]);w.add(badge);scene.buildingBadges.push(badge);}}
 // Interior is public landscaping; every functional building belongs to a playable tile.
 const riverPoints=[];for(let i=0;i<=32;i++){const x=-17+i*34/32;riverPoints.push([x,.042,Math.sin(x*.21)*.8]);}const riverPositions=[],riverIndices=[];riverPoints.forEach(([x,_y,z],i)=>{riverPositions.push(x,.045,z-.58,x,.045,z+.58);if(i<riverPoints.length-1){const k=i*2;riverIndices.push(k,k+1,k+2,k+1,k+3,k+2);}});const riverGeo=new THREE.BufferGeometry();riverGeo.setAttribute('position',new THREE.Float32BufferAttribute(riverPositions,3));riverGeo.setIndex(riverIndices);riverGeo.computeVertexNormals();mesh(w,riverGeo,waterMaterial(true));for(const a of TILES)for(const id of a.next){const b=TILES[id],ra=a.z-Math.sin(a.x*.21)*.8,rb=b.z-Math.sin(b.x*.21)*.8;if(ra*rb>0||Math.abs(ra-rb)<.01)continue;const t=ra/(ra-rb),x=a.x+(b.x-a.x)*t,z=a.z+(b.z-a.z)*t,bridge=new THREE.Group(),length=1.8;for(let i=0;i<9;i++)box(bridge,'#d5bb88',[0,.16,-length/2+i*length/8],[1.68,.07,length/8]);for(const dx of [-.8,.8])tube(bridge,'#526f65',[[dx,.4,-length/2],[dx,.5,0],[dx,.4,length/2]],.025);bridge.rotation.y=Math.atan2(b.x-a.x,b.z-a.z);bridge.position.set(x,0,z);w.add(bridge);}
 if(scene.tiles[43].next[0]===3){for(const [name,x,z,color]of [['晨光支路',-8,2,'#728b57'],['花园支路',8,-2,'#9a7f59'],['滨河公园',0,3.7,'#5e8b78']]){const badge=new THREE.Sprite(new THREE.SpriteMaterial({map:signTexture(name,{width:256,height:72,background:color,color:'#fff5d9'}),transparent:true,depthTest:false}));badge.position.set(x,.6,z);badge.scale.set(2,.56,1);w.add(badge);}for(const a of TILES)for(const id of a.next){const b=TILES[id],dx=b.x-a.x,dz=b.z-a.z,n=Math.hypot(dx,dz),x=a.x+dx*.62,z=a.z+dz*.62,ux=dx/n,uz=dz/n;const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute([x+ux*.2,.178,z+uz*.2,x-ux*.13-uz*.1,.178,z-uz*.13+ux*.1,x-ux*.13+uz*.1,.178,z-uz*.13-ux*.1],3));mesh(w,geo,new THREE.MeshBasicMaterial({color:'#efddb1',side:THREE.DoubleSide}));}}

 scene.hero=new THREE.Group();w.add(scene.hero);scene.fountain=new THREE.Group();scene.fountainSpray=new FountainSpray(scene.fountain);cylinder(scene.fountain,'#c0b18a',[0,.14,0],.87,.94,.23,64);cylinder(scene.fountain,scene.fountainSpray.poolMaterial,[0,.27,0],.79,.79,.035,64);cylinder(scene.fountain,'#dfceab',[0,.48,0],.13,.19,.5,48);const lip=mesh(scene.fountain,new THREE.TorusGeometry(.85,.035,12,72),'#ddd3ab',[0,.275,0]);lip.rotation.x=Math.PI/2;scene.fountain.position.set(-1,.05,7.5);w.add(scene.fountain);scene.waterJets=Array.from({length:6},(_,i)=>tube(scene.fountain,scene.fountainSpray.jetMaterial,fountainJetPath(i),.013,40,8));
 for(const [x,z,s]of [[-8,6,.9],[-6,7,.85],[4,6,1],[7,5,.9],[-7,-6,.9],[-4,-6,.75],[3,-6,.95],[7,-5.5,.8],[-2,7.5,.6],[1,7.5,.6]])if(TILES.every(t=>Math.hypot(t.lotX-x,t.lotZ-z)>2&&Math.hypot(t.x-x,t.z-z)>1.6))townTree(w,x,z,s);
 for(const [x,z]of [[-3,6.2],[2,6.6],[-5,-6],[5,-6]]){box(w,'#a18a62',[x,.35,z],[.9,.09,.28]);box(w,'#b79c6d',[x,.57,z-.1],[.9,.3,.05]);for(const dx of [-.34,.34])box(w,'#57694f',[x+dx,.2,z],[.055,.3,.23]);}
 for(const t of TILES.filter(t=>t.id%6===2)){const nx=(t.lotX-t.x)/2.3,nz=(t.lotZ-t.z)/2.3;scene.lamp(t.x-nx*1.25,t.z-nz*1.25);}
 for(const [x,z]of [[-19,8],[16,-13]]){const boat=new THREE.Group();ball(boat,'#eee4c8',[0,0,0],[1.2,.22,.45]);box(boat,'#5c8891',[0,.2,0],[1.25,.3,.55]);box(boat,'#fff0cf',[0,.4,0],[1.3,.06,.65]);boat.position.set(x,-.47,z);w.add(boat);scene.floats.push(boat);}
 scene.ripples=[];for(const o of [scene.fountain,...scene.floats,...scene.ripples])o.userData.dynamic=true;scenicDetails(scene);batchStatic(w);
}
